<section class="card chat" id="chat"><div class="section-head compact"><div><h2>Auftragschat</h2><p class="muted"><?=$chatReadonly?'Der Chat ist nach Abschluss des Auftrags schreibgeschützt.':'Fragen und Mitteilungen zu diesem Auftrag.'?></p></div><?php if($chatReadonly):?><span class="seller-status">Nur lesen</span><?php endif;?></div><div class="chat-log"><?php foreach($messages as $m):?><div class="message <?=$m['sender_type']?>"><small><?=App\Core\View::e($senderLabels[$m['sender_type']]??$m['sender_type'])?> · <?=date('d.m. H:i',strtotime($m['created_at']))?></small><p><?=nl2br(App\Core\View::e($m['message']))?></p></div><?php endforeach;?></div><?php if(!$chatReadonly):?><form method="post" action="/konto/auftraege/<?=$order['id']?>/chat" class="chat-form"><?=App\Core\Csrf::field()?><textarea name="message" rows="3" required placeholder="Nachricht schreiben"></textarea><button class="btn primary">Senden</button></form><?php endif;?></section></main>